// Project Gantt: views Gantt, Table, Departments, This week, Timeline events.
// Data in Supabase: tasks, task_dependencies, timeline_events. Editing reserved to admins.
// Planning model:
//   planned start / planned end (the bar), optional deadline (commitment; the gap is the margin),
//   actual start / completion dates and "blocked" flag (facts) -> derived status.
//   A task with subtasks: dates and status calculated from the subtasks (roll-up in the database).
// Codes are generated by the database: <department>-<nn>, subtasks <parent>.<n>.
// Every save is checked against concurrent changes (tasks.updated_at).
import { supabase } from './config.js';
import { initProtectedPage, friendlyError } from './auth.js';
import { formatDate, TIME_ZONE } from './format.js';
import { icon } from './icons.js';

/* ---------- constants ---------- */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DEPTS = ['SYS', 'ELE', 'SFW', 'AOCS', 'THM', 'TTC', 'OUT', 'MGT'];
const DEPT_NAMES = {
  SYS: 'Systems', ELE: 'Electronics', SFW: 'Software', AOCS: 'AOCS', THM: 'Thermal-mechanical',
  TTC: 'Telecommunications', OUT: 'Outreach', MGT: 'Management',
};
const STATUS = {
  planned:  'Planned',
  late_start: 'Not started (late)',
  progress: 'In progress',
  overdue:  'Overdue',
  done:     'Done',
};
const VIEWS = [['gantt', 'Gantt'], ['table', 'Table'], ['depts', 'Departments'], ['week', 'This week'], ['events', 'Timeline events']];
const ZOOMS = [3, 5, 7, 10, 14];   // pixels per day
const UNDO_MS = 10000;

/* ---------- utilities ---------- */
const dn = (i) => { const p = i.split('-').map(Number); return Math.round(Date.UTC(p[0], p[1] - 1, p[2]) / 864e5); };
const iso = (n) => new Date(n * 864e5).toISOString().slice(0, 10);
const fmtS = (i) => { const p = i.split('-').map(Number); return `${p[2]} ${MON[p[1] - 1]}`; };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const TODAY = new Intl.DateTimeFormat('en-CA', { timeZone: TIME_ZONE }).format(new Date()); // YYYY-MM-DD
const TN = dn(TODAY);
const days = (n) => `${n} d`;
const COARSE = typeof window.matchMedia === 'function' && window.matchMedia('(pointer: coarse)').matches;

const stored = (key, fallback) => { try { const v = localStorage.getItem(key); return v == null ? fallback : JSON.parse(v); } catch { return fallback; } };
const store = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* storage unavailable */ } };
const DEFAULT_PX = window.matchMedia('(max-width: 640px)').matches ? ZOOMS[0] : 7;

// Message at the bottom, optionally with an action button (e.g. Undo)
function toast(message, action) {
  const t = document.getElementById('toast');
  t.innerHTML = '';
  t.appendChild(document.createTextNode(message));
  if (action) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'link';
    b.textContent = action.label;
    b.addEventListener('click', () => { t.hidden = true; action.run(); });
    t.appendChild(document.createTextNode(' '));
    t.appendChild(b);
  }
  t.hidden = false;
  clearTimeout(toast.h);
  toast.h = setTimeout(() => { t.hidden = true; }, action ? UNDO_MS : 5000);
}

function download(name, text, type) {
  const blob = new Blob([text], { type: `${type};charset=utf-8` });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
}

const ERRORS = {
  'Task modified by someone else': 'The task has been modified by someone else in the meantime: reload and repeat the change.',
  'Task not found': 'The task no longer exists: reload the page.',
  'Not authorized': 'Operation reserved to administrators.',
  'Dependency would create a cycle': 'This dependency would create a loop between tasks.',
  'Subtasks cannot have subtasks': 'A subtask cannot contain other subtasks.',
  'Actual dates cannot be in the future': 'Start and completion dates cannot be in the future.',
  'Dates of a task with subtasks are calculated': 'The dates of a task with subtasks are calculated from the subtasks: change the subtasks.',
  'Department required': 'Select the department.',
  'Department of a task cannot be changed': 'The department of a task cannot be changed (it defines the code).',
  'Code cannot be changed': 'The code cannot be changed.',
  'Parent cannot be changed': 'The parent task cannot be changed.',
};
function errorText(error) {
  const m = error?.message ?? String(error);
  if (/tasks_check/.test(m)) return 'The planned end cannot precede the planned start.';
  if (/tasks_completed_check/.test(m)) return 'A task can be completed only after it has been started, and not before its start date.';
  if (/tasks_blocked_check/.test(m)) return 'Give the reason why the task is blocked.';
  if (/foreign key/.test(m) && /shifts/.test(m)) return 'The task has lab shifts: move them to another task or delete them first.';
  return ERRORS[m] ?? friendlyError(error);
}

/* ---------- state ---------- */
const profile = await initProtectedPage('gantt');
const ADMIN = profile?.role === 'admin';
let ROWS = [];
let DEPS = [];
let EVENTS = [];
let PEOPLE = new Map();       // profile id -> { name, role, status }
let DEPT_LEADERS = new Map(); // department -> leader id
let ALL = [];                 // derived, ordered
const ui = {
  view: 'gantt', dept: 'All', deptView: 'SYS', q: '', hideDone: false, confirmDel: null,
  edit: false,
  px: ZOOMS.includes(stored('gantt-px', DEFAULT_PX)) ? stored('gantt-px', DEFAULT_PX) : DEFAULT_PX,
  collapsed: new Set(stored('gantt-collapsed', [])),
};

// Keep the mobile default when the viewport crosses the breakpoint, unless the user chose a zoom.
const mobileQuery = window.matchMedia('(max-width: 640px)');
mobileQuery.addEventListener('change', (e) => {
  if (stored('gantt-px', null) === null) ui.px = e.matches ? ZOOMS[0] : 7;
  render();
});

async function load() {
  const [t, d, ev, pr, tl] = await Promise.all([
    supabase.from('tasks').select('*'),
    supabase.from('task_dependencies').select('task_id, depends_on'),
    supabase.from('timeline_events').select('*'),
    supabase.from('profiles').select('id, full_name, email, role, status'),
    supabase.from('team_leaders').select('team, leader_id'),
  ]);
  const error = t.error || d.error || ev.error || pr.error || tl.error;
  if (error) throw error;
  PEOPLE = new Map(pr.data.map((p) => [p.id, { name: p.full_name ?? p.email, role: p.role, status: p.status }]));
  DEPT_LEADERS = new Map(tl.data.map((x) => [x.team, x.leader_id]));
  ROWS = t.data;
  DEPS = d.data;
  EVENTS = ev.data.sort((a, b) => (a.event_date < b.event_date ? -1 : 1));
}

async function reload(message) {
  try { await load(); } catch (err) { toast(errorText(err)); return; }
  render();
  if (message) toast(message);
}

/* ---------- leaders ---------- */
// Same rule as the database view task_leaders: override > department leader > parent task leader.
const validLeader = (id) => {
  const p = id ? PEOPLE.get(id) : null;
  return p && p.status === 'active' && (p.role === 'teamleader' || p.role === 'admin') ? id : null;
};
const deptLeader = (dept) => validLeader(DEPT_LEADERS.get(dept));
const eligibleLeaders = () => [...PEOPLE.entries()].filter(([id]) => validLeader(id))
  .sort((a, b) => a[1].name.localeCompare(b[1].name));
const nameOfPerson = (id) => (id ? PEOPLE.get(id)?.name ?? '?' : '');

/* ---------- derived model ---------- */
function statusOf(t) {
  if (t.completed_on) return 'done';
  if (t.started_on) return TODAY > t.end_date ? 'overdue' : 'progress';
  return TODAY >= t.start_date ? 'late_start' : 'planned';
}

function cmp(a, b) {
  return a.start_date < b.start_date ? -1 : a.start_date > b.start_date ? 1
    : a.code.localeCompare(b.code, 'en', { numeric: true });
}

function build() {
  const byId = new Map(ROWS.map((r) => [r.id, r]));
  const requiredBy = new Map();
  const dependsOn = new Map();
  DEPS.forEach(({ task_id: t, depends_on: d }) => {
    if (!requiredBy.has(d)) requiredBy.set(d, []);
    requiredBy.get(d).push(t);
    if (!dependsOn.has(t)) dependsOn.set(t, []);
    dependsOn.get(t).push(d);
  });
  const children = new Map();
  ROWS.forEach((r) => {
    if (r.parent_id && byId.has(r.parent_id)) {
      if (!children.has(r.parent_id)) children.set(r.parent_id, []);
      children.get(r.parent_id).push(r);
    }
  });

  const derived = ROWS.map((r) => {
    const t = { ...r };
    const kids = children.get(t.id) ?? [];
    t.hasChildren = kids.length > 0;
    t.status = statusOf(t);
    t.blockedAny = t.blocked || kids.some((k) => k.blocked && !k.completed_on);
    t.margin = t.deadline ? dn(t.deadline) - dn(t.end_date) : null;
    t.atRisk = !t.completed_on && Boolean(t.deadline) && (t.end_date > t.deadline || TODAY > t.deadline);
    t.lateDone = Boolean(t.completed_on && t.deadline && t.completed_on > t.deadline);
    t.requiredByIds = requiredBy.get(t.id) ?? [];
    t.dependsOnIds = dependsOn.get(t.id) ?? [];
    t.requiredBy = t.requiredByIds.map((id) => byId.get(id)?.code).filter(Boolean).sort();
    t.dependsOn = t.dependsOnIds.map((id) => byId.get(id)?.code).filter(Boolean).sort();
    t.parentCode = t.parent_id ? byId.get(t.parent_id)?.code : null;
    // Dependency check: starts before the end of a task it depends on
    t.depConflict = t.dependsOnIds.map((id) => byId.get(id)).filter((x) => x && x.end_date >= t.start_date).map((x) => x.code);
    return t;
  });

  // Effective leader
  const own = new Map(derived.map((t) => [t.id, validLeader(t.leader_id) ?? deptLeader(t.department)]));
  derived.forEach((t) => {
    const override = validLeader(t.leader_id);
    const dept = deptLeader(t.department);
    const parent = t.parent_id ? own.get(t.parent_id) ?? null : null;
    t.defaultLeader = dept ?? parent;
    t.defaultSource = dept ? `${t.department} leader` : parent ? 'parent task leader' : null;
    t.leader = override ?? t.defaultLeader;
    t.leaderName = nameOfPerson(t.leader);
    t.invalidOverride = Boolean(t.leader_id && !override);
  });

  // Order: top-level tasks by planned start, each followed by its subtasks
  const out = [];
  derived.filter((t) => !t.parent_id || !byId.has(t.parent_id)).sort(cmp).forEach((p) => {
    p.depth = 0;
    out.push(p);
    derived.filter((c) => c.parent_id === p.id).sort(cmp).forEach((c) => { c.depth = 1; out.push(c); });
  });
  return out;
}

const deptOf = (t) => [t.department, ...t.teams.filter((k) => k !== t.department)];

function filterTasks(list, dept, q, hideDone) {
  return list.filter((t) => {
    if (dept !== 'All' && !deptOf(t).includes(dept)) return false;
    if (hideDone && t.status === 'done') return false;
    if (q) {
      const s = `${t.code} ${t.name} ${t.people ?? ''} ${t.leaderName}`.toLowerCase();
      if (!s.includes(q.toLowerCase())) return false;
    }
    return true;
  });
}

/* ---------- common pieces ---------- */
function statusBadge(t) {
  return `<span class="st ${t.status}">${STATUS[t.status]}${t.lateDone ? ' (late)' : ''}</span>` +
    (t.blockedAny ? '<span class="st blocked" title="' + esc(t.blocked ? t.blocked_reason : 'Contains blocked subtasks') + '">Blocked</span>' : '') +
    (t.atRisk ? '<span class="st risk" title="Planned end after the deadline, or deadline passed">At risk</span>' : '');
}

function stats(ts) {
  const count = (f) => ts.filter(f).length;
  const leaves = ts.filter((t) => !t.hasChildren);
  const done = count((t) => t.status === 'done');
  const noLeader = count((t) => t.status !== 'done' && !t.leader);
  const item = (label, n, bad) => `<li>${label}<b class="${bad && n ? 'bad' : ''}">${n}</b></li>`;
  let h = `<li>Done<b>${done}/${ts.length}</b></li>` +
    item('In progress', count((t) => t.status === 'progress')) +
    item('Overdue', count((t) => t.status === 'overdue'), true) +
    item('Late start', count((t) => t.status === 'late_start'), true) +
    item('Blocked', leaves.filter((t) => t.blocked && !t.completed_on).length, true) +
    item('At risk', count((t) => t.atRisk), true) +
    item('Open without leader', noLeader, true);
  ts.filter((t) => t.milestone_label).sort((a, b) => (a.end_date < b.end_date ? -1 : 1)).forEach((m) => {
    h += `<li>Days to ${esc(m.milestone_label.toLowerCase())}<b>${dn(m.deadline ?? m.end_date) - TN}</b></li>`;
  });
  document.getElementById('stats').innerHTML = h;
}

function toolbar(gantt) {
  const dept = `<label>Department <select id="gdept">${['All', ...DEPTS].map((k) =>
    `<option value="${k}"${k === ui.dept ? ' selected' : ''}>${k === 'All' ? 'All' : `${k} – ${DEPT_NAMES[k]}`}</option>`).join('')}</select></label>`;
  const ganttTools = gantt ? `<span class="zoom" role="group" aria-label="Zoom">
      <button type="button" class="secondary" data-act="zoom-out" title="Zoom out"${ui.px === ZOOMS[0] ? ' disabled' : ''}>−</button>
      <button type="button" class="secondary" data-act="zoom-in" title="Zoom in"${ui.px === ZOOMS[ZOOMS.length - 1] ? ' disabled' : ''}>+</button></span>
    <button type="button" class="secondary btn-icon" data-act="expand-all" title="Expand all" aria-label="Expand all">${icon('chevrons-down')}</button>
    <button type="button" class="secondary btn-icon" data-act="collapse-all" title="Collapse all" aria-label="Collapse all">${icon('chevrons-up')}</button>
    ${ADMIN && !COARSE ? `<label class="chk edit-toggle${ui.edit ? ' on' : ''}"><input type="checkbox" id="edit-mode"${ui.edit ? ' checked' : ''}> Edit timeline</label>` : ''}` : '';
  const mode = !ADMIN ? 'Read only: click a task to see its details.'
    : gantt && ui.edit ? 'Edit timeline ON: drag a bar to move it, its ends to change start or end. Esc cancels a drag.'
      : 'Click a task to open it.';
  return `<div class="bar-tools">${ADMIN ? `<button type="button" class="btn-with-icon" data-act="new-task">${icon('plus')} New task</button>` : ''}${dept}${ganttTools}
    <input id="q" type="search" placeholder="Search task or person" value="${esc(ui.q)}" aria-label="Search">
    <label class="chk"><input type="checkbox" id="hd"${ui.hideDone ? ' checked' : ''}> Hide done</label>
    <button type="button" class="secondary btn-icon" data-act="csv" title="Export CSV" aria-label="Export CSV">${icon('download')}</button>
    <button type="button" class="secondary btn-icon" data-act="reload" title="Reload" aria-label="Reload">${icon('rotate-cw')}</button>
    <span class="mode">${mode}</span>
  </div>`;
}

function legend() {
  return `<ul class="legend">${Object.entries(STATUS).map(([k, l]) => `<li><span class="sw ${k}"></span>${l}</li>`).join('')}
    <li><span class="sw blocked"></span>Blocked</li>
    <li><span class="dl"></span>Deadline (dotted: margin)</li>
    <li><span class="dl risk"></span>At risk</li>
    <li>→ dependency (red dashed: starts before the end of the task it depends on)</li></ul>`;
}

/* ---------- Gantt view ---------- */
function gantt(all) {
  const ts = filterTasks(all, ui.dept, ui.q, ui.hideDone)
    .filter((t) => !(t.parent_id && ui.collapsed.has(t.parent_id)));
  if (!all.length) {
    return toolbar(true) + `<div class="gwrap"><div class="empty">No task yet.${ADMIN ? ' Use "New task" to create the first one.' : ''}</div></div>`;
  }
  if (!ts.length) return toolbar(true) + legend() + '<div class="gwrap"><div class="empty">No task matches these filters.</div></div>';

  const byId = new Map(all.map((t) => [t.id, t]));
  const allDays = [TN, ...EVENTS.map((e) => dn(e.event_date))];
  all.forEach((t) => { allDays.push(dn(t.start_date), dn(t.end_date)); if (t.deadline) allDays.push(dn(t.deadline)); });
  const d0 = new Date(Math.min(...allDays) * 864e5);
  const d1 = new Date(Math.max(...allDays) * 864e5);
  const RS = Date.UTC(d0.getUTCFullYear(), d0.getUTCMonth(), 1) / 864e5;
  const RE = Date.UTC(d1.getUTCFullYear(), d1.getUTCMonth() + 1, 0) / 864e5;
  const PX = ui.px, RH = 30, HH = 56, W = (RE - RS + 1) * PX + 90;
  const lw = window.innerWidth <= 640 ? 150 : 330;
  const x = (day) => (day - RS) * PX;

  let months = '', ticks = '', refs = '';
  for (let y = d0.getUTCFullYear(), m = d0.getUTCMonth(); ; m++) {
    const a = Date.UTC(y, m, 1) / 864e5, b = Date.UTC(y, m + 1, 1) / 864e5;
    if (a > RE) break;
    const dt = new Date(a * 864e5);
    months += `<div class="mo" style="left:${x(a)}px;width:${(Math.min(b, RE + 1) - a) * PX}px">${MON[dt.getUTCMonth()]} ${dt.getUTCFullYear()}</div>`;
  }
  for (let d = RS; d <= RE; d++) {
    const dt = new Date(d * 864e5);
    if (dt.getUTCDay() === 1) ticks += `<span class="wk" style="left:${x(d)}px">${dt.getUTCDate()}</span>`;
  }

  const lines = [];
  refs += `<span class="ref today" style="left:${x(TN) + PX / 2}px">today</span>`;
  lines.push([x(TN) + PX / 2, 'var(--accent)', '']);
  all.filter((t) => t.milestone_label).forEach((m) => {
    const px = x(dn(m.deadline ?? m.end_date)) + PX / 2;
    refs += `<span class="ref mile" style="left:${px}px">${esc(m.milestone_label)}</span>`;
    lines.push([px, 'var(--text)', '4 3']);
  });
  EVENTS.forEach((ev) => {
    const px = x(dn(ev.event_date)) + PX / 2;
    const tip = `${ev.label} · ${formatDate(ev.event_date)}${ev.note ? `\n${ev.note}` : ''}`;
    refs += `<span class="ref event" style="left:${px}px" title="${esc(tip)}">${esc(ev.label)}</span>`;
    lines.push([px, 'var(--st-risk)', '4 3']);
  });

  let rows = '';
  const pos = {};
  ts.forEach((t, i) => {
    const s = dn(t.start_date), e = dn(t.end_date);
    const l = x(s), w = Math.max((e - s + 1) * PX, 6);
    pos[t.id] = { i, l, r: l + w };
    const tip = `${t.code} · ${t.name}\n${STATUS[t.status]}${t.blockedAny ? ' · BLOCKED' : ''}${t.atRisk ? ' · AT RISK' : ''}` +
      `\nPlanned: ${formatDate(t.start_date)} – ${formatDate(t.end_date)} (${days(e - s + 1)})` +
      (t.deadline ? `\nDeadline: ${formatDate(t.deadline)} · margin ${days(t.margin)}` : '') +
      (t.started_on ? `\nStarted: ${formatDate(t.started_on)}` : '') + (t.completed_on ? ` · Completed: ${formatDate(t.completed_on)}` : '') +
      `\nLeader: ${t.leaderName || '—'}${t.people ? ` · People: ${t.people}` : ''}` +
      (t.blocked ? `\nBlocked: ${t.blocked_reason}` : '') + (t.note ? `\n${t.note}` : '');
    const nKids = all.filter((c) => c.parent_id === t.id).length;
    const caret = t.hasChildren
      ? `<button type="button" class="caret" data-toggle="${t.id}" aria-expanded="${!ui.collapsed.has(t.id)}"
          title="${ui.collapsed.has(t.id) ? `Show ${nKids} subtasks` : 'Hide subtasks'}">${ui.collapsed.has(t.id) ? icon('chevron-right', 12) : icon('chevron-down', 12)}</button>`
      : '<span class="caret-sp"></span>';
    const addSub = ADMIN && t.depth === 0
      ? `<button type="button" class="addsub" data-addsub="${t.id}" title="Add a subtask to ${esc(t.code)}">+</button>` : '';
    const editable = ADMIN && ui.edit && !COARSE;
    const handles = editable && !t.hasChildren ? '<span class="hd l"></span><span class="hd r"></span>' : '';
    // Deadline marker and margin
    let dl = '';
    if (t.deadline) {
      const dx = x(dn(t.deadline)) + PX / 2;
      if (t.margin > 0) dl += `<span class="margin" style="left:${l + w}px;width:${Math.max(dx - (l + w), 0)}px"></span>`;
      dl += `<span class="dl${t.atRisk ? ' risk' : ''}" style="left:${dx}px" title="Deadline ${formatDate(t.deadline)}"></span>`;
    }
    const label = `${t.depth ? '' : caret}<a href="#" class="tlink" data-open="${t.id}"><span class="code">${esc(t.code)}</span><span class="n">${esc(t.name)}</span></a>` +
      `${t.blockedAny ? '<span class="flag" role="img" aria-label="Blocked" title="Blocked"></span>' : ''}${addSub}`;
    rows += `<div class="grow" style="height:${RH}px">
      <div class="glabel${t.depth ? ' sub' : ''}" title="${esc(tip)}">${label}</div>
      <div class="track" style="width:${W}px">
        <div class="bar ${t.status}${t.hasChildren ? ' parent' : ''}${t.blockedAny ? ' blocked' : ''}${editable ? ' drag' : ''}"
          data-bar="${t.id}" data-open="${t.id}" style="left:${l}px;width:${w}px" title="${esc(tip)}">${handles}</div>
        ${dl}
        <span class="bd" style="left:${Math.max(l + w, t.deadline ? x(dn(t.deadline)) + PX : 0) + 6}px">${fmtS(t.end_date)}</span>
      </div></div>`;
  });

  let arrows = '';
  ts.forEach((t) => t.requiredByIds.forEach((succId) => {
    const a = pos[t.id], b = pos[succId];
    if (!a || !b) return;
    const y1 = a.i * RH + RH / 2, y2 = b.i * RH + RH / 2, x1 = a.r, x2 = b.l;
    const tight = t.end_date >= byId.get(succId).start_date;
    const col = tight ? 'var(--st-late)' : 'var(--muted)';
    arrows += `<path d="M${x1} ${y1} H${x1 + 8} V${y2} H${x2}" fill="none" stroke="${col}" stroke-width="1.2"${tight ? ' stroke-dasharray="3 2"' : ''}/>` +
      `<path d="M${x2} ${y2} l-5 -3 v6 z" fill="${col}"/>`;
  }));
  const svg = `<svg class="arrows" style="left:${lw}px;top:${HH}px" width="${W}" height="${ts.length * RH}" aria-hidden="true">` +
    lines.map(([lx, c, dash]) => `<line x1="${lx}" x2="${lx}" y1="0" y2="${ts.length * RH}" stroke="${c}" stroke-width="1"${dash ? ` stroke-dasharray="${dash}"` : ''} opacity=".7"/>`).join('') +
    arrows + '</svg>';

  ui.ganttStart = RS;
  return toolbar(true) + legend() +
    `<div class="gwrap${ui.edit && ADMIN && !COARSE ? ' editing' : ''}" id="gw"><div class="ginner" style="--lw:${lw}px;--wk:${7 * PX}px;--off:${((1 - new Date(RS * 864e5).getUTCDay() + 7) % 7) * PX}px">
      <div class="grow hdr" style="height:${HH}px"><div class="glabel">Task</div><div class="track" style="width:${W}px">${months}${ticks}${refs}</div></div>
      ${rows}${svg}</div></div>
    <p class="hint">Bars: planned start to planned end. Diamond: deadline; the dotted segment is the margin.
    A task with subtasks (thin bar) takes its dates from the subtasks.</p>`;
}

/* ---------- Table view (read only) ---------- */
function table(all) {
  const ts = filterTasks(all, ui.dept, ui.q, ui.hideDone);
  const row = (t) => `<tr class="r-${t.status}${t.depth ? ' sub' : ''}" data-open="${t.id}" tabindex="0">
    <td><span class="code">${esc(t.code)}</span></td>
    <td>${esc(t.name)}${t.note ? `<span class="req">${esc(t.note)}</span>` : ''}</td>
    <td>${esc(t.department)}${t.teams.filter((k) => k !== t.department).length ? `<span class="req">+ ${esc(t.teams.filter((k) => k !== t.department).join(', '))}</span>` : ''}</td>
    <td>${esc(t.leaderName || '—')}${t.people ? `<span class="req">${esc(t.people)}</span>` : ''}</td>
    <td>${statusBadge(t)}</td>
    <td class="mono x">${formatDate(t.start_date)}</td>
    <td class="mono">${formatDate(t.end_date)}</td>
    <td class="mono">${t.deadline ? formatDate(t.deadline) : '—'}</td>
    <td class="mono ${t.margin != null && t.margin < 0 ? 'bad' : ''}">${t.margin != null ? days(t.margin) : '—'}</td>
    <td class="mono x">${t.started_on ? formatDate(t.started_on) : '—'}</td>
    <td class="mono">${t.completed_on ? formatDate(t.completed_on) : '—'}</td>
    <td class="mono">${esc(t.dependsOn.join(', '))}</td></tr>`;
  return toolbar(false) +
    `<div class="tw"><table class="ro"><thead><tr>
      <th>Code</th><th>Activity</th><th>Department</th><th>Leader / people</th><th>Status</th>
      <th class="x">Planned start</th><th>Planned end</th><th>Deadline</th><th>Margin</th>
      <th class="x">Started</th><th>Completed</th><th>Depends on</th>
    </tr></thead><tbody>${ts.map(row).join('') || '<tr><td colspan="12" class="hint">No task.</td></tr>'}</tbody></table></div>
    <p class="hint">Read only. Click a row to open the task${ADMIN ? ' and edit it' : ''}.</p>`;
}

/* ---------- Departments view ---------- */
function departments(all) {
  const dept = ui.deptView;
  const ts = all.filter((t) => deptOf(t).includes(dept));
  const chips = '<div class="team-chips">' + DEPTS.map((k) => {
    const n = all.filter((t) => deptOf(t).includes(k)).length;
    return `<button type="button" data-act="dept" data-t="${k}" aria-pressed="${k === dept}">${k} · ${n}</button>`;
  }).join('') + '</div>';
  const lead = deptLeader(dept);
  let h = `${chips}<h2 class="g-h2">${dept} – ${DEPT_NAMES[dept]} <small>leader ${esc(nameOfPerson(lead) || 'not set')} ·
    ${ts.length} tasks, ${ts.filter((t) => t.status === 'done').length} done</small></h2>`;
  if (!ts.length) return `${h}<div class="empty">No task for this department.</div>`;
  h += `<div class="tw short"><table class="ro"><thead><tr><th>Code</th><th>Activity</th><th>Role</th><th>Leader</th><th>Status</th><th class="x">Planned</th><th>Deadline</th></tr></thead><tbody>` +
    ts.map((t) => `<tr class="r-${t.status}${t.depth ? ' sub' : ''}" data-open="${t.id}" tabindex="0"><td><span class="code">${esc(t.code)}</span></td>
      <td>${esc(t.name)}</td><td>${t.department === dept ? 'owner' : 'involved'}</td><td>${esc(t.leaderName || '—')}</td>
      <td>${statusBadge(t)}</td><td class="mono x">${fmtS(t.start_date)} – ${fmtS(t.end_date)}</td>
      <td class="mono">${t.deadline ? formatDate(t.deadline) : '—'}</td></tr>`).join('') +
    '</tbody></table></div><p class="hint">"Owner": task of the department; "involved": task of another department in which this one takes part.</p>';
  return h;
}

/* ---------- This week view ---------- */
function week(all) {
  const open = all.filter((t) => t.status !== 'done');
  const due = (t) => t.deadline ?? t.end_date;
  const lists = [
    ['Blocked', open.filter((t) => t.blocked), 'No blocked task.'],
    ['Overdue (planned end passed, not completed)', open.filter((t) => t.status === 'overdue' || (t.status === 'late_start' && t.end_date < TODAY)), 'No overdue task.'],
    ['Deadline in the next 7 days', open.filter((t) => t.deadline && t.deadline >= TODAY && dn(t.deadline) <= TN + 7), 'No deadline in the next 7 days.'],
    ['Should have started (planned start passed, not started)', open.filter((t) => t.status === 'late_start' && t.end_date >= TODAY), 'All tasks planned to start are started.'],
    ['Starting in the next 7 days', open.filter((t) => t.status === 'planned' && dn(t.start_date) <= TN + 7), 'No start planned in the next 7 days.'],
  ];
  const list = ([title, items, none]) => {
    const h = `<h2 class="g-h2">${title} <small>${items.length}</small></h2>`;
    if (!items.length) return `${h}<div class="empty" style="padding:14px;text-align:left">${none}</div>`;
    return h + '<div class="tw short"><table class="ro"><tbody>' + items.map((t) =>
      `<tr class="r-${t.status}" data-open="${t.id}" tabindex="0"><td style="width:72px"><span class="code">${esc(t.code)}</span></td>
        <td>${esc(t.name)}<span class="req">${esc(t.leaderName ? `Leader: ${t.leaderName}` : 'No leader')}${t.blocked ? ` · Blocked: ${esc(t.blocked_reason)}` : ''}</span></td>
        <td class="mono" style="white-space:nowrap">${fmtS(t.start_date)} – ${fmtS(t.end_date)}<span class="req">${t.deadline ? `deadline ${fmtS(due(t))}` : ''}</span></td>
        <td style="width:190px">${statusBadge(t)}</td></tr>`).join('') + '</tbody></table></div>';
  };
  return `<p class="g-sub" style="margin-bottom:6px">For the board meeting · today ${formatDate(TODAY)}</p>${lists.map(list).join('')}`;
}

/* ---------- Timeline events view ---------- */
function events() {
  const dis = ADMIN ? '' : ' disabled';
  const rows = EVENTS.map((ev) => `<tr>
    <td><input type="date" data-ev="${ev.id}" data-f="event_date" value="${esc(ev.event_date)}" aria-label="Date"${dis}></td>
    <td><input type="text" data-ev="${ev.id}" data-f="label" value="${esc(ev.label)}" maxlength="40" aria-label="Label"${dis}></td>
    <td><input type="text" data-ev="${ev.id}" data-f="note" value="${esc(ev.note ?? '')}" placeholder="Note" aria-label="Note"${dis}></td>
    <td class="mono">${days(dn(ev.event_date) - TN)}</td>
    <td style="white-space:nowrap">${!ADMIN ? '' : ui.confirmDel === `ev${ev.id}`
      ? `<button type="button" class="act danger" data-act="evdel2" data-id="${ev.id}">Delete?</button>`
      : `<button type="button" class="act secondary" data-act="evdel" data-id="${ev.id}" title="Delete the event" aria-label="Delete the event">${icon('x', 12)}</button>`}</td></tr>`).join('');
  const addRow = !ADMIN ? '' : `<tr>
    <td><input type="date" id="ev-date"></td>
    <td><input type="text" id="ev-label" maxlength="40" placeholder="Label"></td>
    <td><input type="text" id="ev-note" placeholder="Note"></td>
    <td colspan="2"><button type="button" data-act="evadd">Add event</button></td></tr>`;
  return `<p class="g-sub" style="margin-bottom:8px">Fixed external dates around which the work is planned. They are shown as vertical lines in the Gantt; they are not tasks.</p>
    <div class="tw short"><table><thead><tr><th>Date</th><th>Label</th><th>Note</th><th>From today</th><th></th></tr></thead>
    <tbody>${rows || (ADMIN ? '' : '<tr><td colspan="5" class="hint">No event.</td></tr>')}${addRow}</tbody></table></div>`;
}

async function eventWrite(query, message) {
  const { error } = await query;
  ui.confirmDel = null;
  if (error) toast(/timeline_events_label_check/.test(error.message) ? 'Label required (max 40 characters).' : errorText(error));
  await reload(error ? undefined : message);
}

/* ---------- CSV ---------- */
function exportCsv() {
  const rows = [['Code', 'Parent', 'Activity', 'Department', 'Involved', 'Leader', 'People', 'Status', 'Blocked', 'At risk',
    'Planned start', 'Planned end', 'Deadline', 'Margin (d)', 'Started', 'Completed', 'Depends on', 'Required by', 'Milestone', 'Note']];
  ALL.forEach((t) => rows.push([t.code, t.parentCode ?? '', t.name, t.department, t.teams.filter((k) => k !== t.department).join(' '),
    t.leaderName, t.people ?? '', STATUS[t.status], t.blocked ? t.blocked_reason : '', t.atRisk ? 'yes' : '',
    formatDate(t.start_date), formatDate(t.end_date), t.deadline ? formatDate(t.deadline) : '', t.margin ?? '',
    t.started_on ? formatDate(t.started_on) : '', t.completed_on ? formatDate(t.completed_on) : '',
    t.dependsOn.join(' '), t.requiredBy.join(' '), t.milestone_label ?? '', t.note ?? '']));
  const csv = rows.map((r) => r.map((v) => `"${String(v).replace(/"/g, '""')}"`).join(';')).join('\r\n');
  download(`gantt_${TODAY}.csv`, `﻿${csv}`, 'text/csv');
}

/* ---------- task editor ---------- */
// Does `from` depend, directly or not, on `to`? edges: id -> Set of ids it depends on
function dependsOnPath(edges, from, to) {
  const seen = new Set();
  const stack = [from];
  while (stack.length) {
    const n = stack.pop();
    if (n === to) return true;
    if (seen.has(n)) continue;
    seen.add(n);
    (edges.get(n) ?? []).forEach((m) => stack.push(m));
  }
  return false;
}

function graphWith(taskId, dependsOn, requiredBy) {
  const edges = new Map();
  DEPS.forEach(({ task_id: t, depends_on: d }) => {
    if (t === taskId || d === taskId) return;
    if (!edges.has(t)) edges.set(t, new Set());
    edges.get(t).add(d);
  });
  edges.set(taskId, new Set(dependsOn));
  requiredBy.forEach((r) => { if (!edges.has(r)) edges.set(r, new Set()); edges.get(r).add(taskId); });
  return edges;
}

const modal = () => document.getElementById('g-modal');
function closeModal() { const m = modal(); m.hidden = true; m.innerHTML = ''; }
function requestClose() {
  if (modal().dirty && !window.confirm('Discard the unsaved changes?')) return;
  closeModal();
}

// id: existing task, or null for a new one; preset: initial values of a new task
function openEditor(id, preset = {}) {
  const t = id != null ? ALL.find((x) => x.id === id) : null;
  if (id != null && !t) { toast(ERRORS['Task not found']); return; }
  const ro = !ADMIN;
  const dis = ro ? ' disabled' : '';
  const v = t ? { ...t } : {
    department: '', name: '', parent_id: null, start_date: TODAY, end_date: iso(TN + 6), deadline: null,
    started_on: null, completed_on: null, blocked: false, blocked_reason: '', leader_id: null, people: '', note: '',
    teams: [], milestone_label: '', ...preset,
  };
  const parent = v.parent_id ? ALL.find((x) => x.id === v.parent_id) : null;
  const children = t ? ALL.filter((x) => x.parent_id === t.id) : [];
  const calc = t && t.hasChildren;          // dates and progress calculated from the subtasks
  const deps = new Set(t ? t.dependsOnIds : preset.dependsOnIds ?? []);
  const reqs = new Set(t ? t.requiredByIds : []);
  const self = id ?? -1;
  const deptLocked = ro || (t && !t.parent_id);   // department of a top-level task defines its code
  const title = t ? `${esc(t.code)} – ${esc(t.name)}` : parent ? `New subtask of ${esc(parent.code)}` : 'New task';
  const codeInfo = t ? `<span class="code big">${esc(t.code)}</span>`
    : `<span class="hint" id="ed-codeinfo">${parent ? `${esc(parent.code)}.n` : 'Department-nn'} – assigned on creation</span>`;

  const m = modal();
  m.dirty = false;
  m.innerHTML = `<div class="mbox wide" role="dialog" aria-modal="true" aria-labelledby="ed-title">
    <h2 id="ed-title">${title}</h2>
    <p class="meta">${t ? `${statusBadge(t)} · last change ${t.updated_at ? new Date(t.updated_at).toLocaleString('en-GB', { timeZone: TIME_ZONE, dateStyle: 'short', timeStyle: 'short' }) : '—'}${t.updated_by ? ` by ${esc(nameOfPerson(t.updated_by))}` : ''}` : 'Fields marked * are required.'}</p>
    <form id="ed-form" novalidate>
      <div class="ed-grid">
        <div><span class="lbl">Code</span>${codeInfo}</div>
        <div><label for="ed-dept">Department *</label><select id="ed-dept"${deptLocked ? ' disabled' : ''}
            title="${t && !t.parent_id ? 'The department of a task defines its code and cannot be changed' : ''}">
          ${t ? '' : '<option value="">— select —</option>'}${DEPTS.map((k) => `<option value="${k}"${k === v.department ? ' selected' : ''}>${k} – ${DEPT_NAMES[k]}</option>`).join('')}</select></div>
        <div><span class="lbl">Parent task</span>${parent ? `<a href="#" data-goto="${parent.id}"><span class="code">${esc(parent.code)}</span> ${esc(parent.name)}</a>` : '<span class="hint">none (top-level task)</span>'}</div>
        <div class="span3"><label for="ed-name">Activity *</label><input id="ed-name" maxlength="200" value="${esc(v.name)}" required${dis}></div>

        <div><label for="ed-start">Planned start *</label><input id="ed-start" type="date" value="${esc(v.start_date)}"${ro || calc ? ' disabled' : ''}></div>
        <div><label for="ed-end">Planned end *</label><input id="ed-end" type="date" value="${esc(v.end_date)}"${ro || calc ? ' disabled' : ''}>
          <span class="req" id="ed-dur"></span></div>
        <div><label for="ed-deadline">Deadline</label><input id="ed-deadline" type="date" value="${esc(v.deadline ?? '')}"${dis}>
          <span class="req" id="ed-margin"></span></div>
        ${calc ? '<p class="hint span3">Planned dates, start and completion are calculated from the subtasks. The deadline of this task gives the margin of the whole work package.</p>' : ''}

        <div><label for="ed-leader">Leader</label><select id="ed-leader"${dis}></select></div>
        <div class="span2"><label for="ed-people">People involved</label><input id="ed-people" maxlength="200" placeholder="Names, recruits, …" value="${esc(v.people ?? '')}"${dis}></div>
        <div class="span3"><span class="lbl">Other departments involved</span><div class="ed-teams">${DEPTS.map((k) =>
          `<label class="pk"><input type="checkbox" name="ed-team" value="${k}"${v.teams.includes(k) ? ' checked' : ''}${dis}> ${k}</label>`).join('')}</div></div>
        <div><label for="ed-milestone">Milestone label</label><input id="ed-milestone" maxlength="40" placeholder="none" value="${esc(v.milestone_label ?? '')}"${dis}></div>
        <div class="span2"><label for="ed-note">Note</label><input id="ed-note" maxlength="500" value="${esc(v.note ?? '')}"${dis}></div>
      </div>

      <h3>Progress</h3>
      <div class="ed-progress">
        <label class="pk"><input type="checkbox" id="ed-started"${v.started_on ? ' checked' : ''}${ro || calc ? ' disabled' : ''}> Started</label>
        <input type="date" id="ed-started-on" max="${TODAY}" value="${esc(v.started_on ?? '')}" aria-label="Start date"${ro || calc || !v.started_on ? ' disabled' : ''}>
        <label class="pk"><input type="checkbox" id="ed-completed"${v.completed_on ? ' checked' : ''}${ro || calc ? ' disabled' : ''}> Completed</label>
        <input type="date" id="ed-completed-on" max="${TODAY}" value="${esc(v.completed_on ?? '')}" aria-label="Completion date"${ro || calc || !v.completed_on ? ' disabled' : ''}>
        ${calc ? '' : `<label class="pk"><input type="checkbox" id="ed-blocked"${v.blocked ? ' checked' : ''}${dis}> Blocked</label>
        <input type="text" id="ed-blocked-reason" maxlength="200" placeholder="Reason (required)" value="${esc(v.blocked_reason ?? '')}"${ro || !v.blocked ? ' disabled' : ''}>`}
      </div>

      <h3>Dependencies</h3>
      <div class="ed-deps">
        <div><span class="lbl">Depends on <span class="hint">(shall end before this task starts)</span></span>
          <div class="chips" id="ed-deps"></div>${ro ? '' : '<select id="ed-add-dep" aria-label="Add a task this one depends on"></select>'}</div>
        <div><span class="lbl">Required by <span class="hint">(cannot start before this task ends)</span></span>
          <div class="chips" id="ed-reqs"></div>${ro ? '' : '<select id="ed-add-req" aria-label="Add a task that depends on this one"></select>'}</div>
      </div>

      <div id="ed-warn"></div>

      ${t && !t.parent_id ? `<h3>Subtasks (${children.length})</h3>
        ${children.length ? `<ul class="ed-children">${children.map((c) => `<li><a href="#" data-goto="${c.id}"><span class="code">${esc(c.code)}</span> ${esc(c.name)}</a>
          <span class="hint">${formatDate(c.start_date)} – ${formatDate(c.end_date)} · ${STATUS[c.status]}${c.blocked ? ' · blocked' : ''}</span></li>`).join('')}</ul>` : '<p class="hint">None.</p>'}
        ${ro ? '' : `<button type="button" class="secondary btn-with-icon" data-ed="add-sub">${icon('plus')} Add subtask</button>`}` : ''}

      ${t ? '<details class="ed-hist" id="ed-hist"><summary>Change history</summary><div id="ed-hist-body"><p class="hint">Loading…</p></div></details>' : ''}

      <p class="message" id="ed-msg" role="alert" hidden></p>
      <div class="buttons">
        ${t && !ro ? `<button type="button" class="danger btn-with-icon" data-ed="delete">${icon('trash-2')} Delete…</button>` : ''}
        ${t && !ro ? `<button type="button" class="secondary btn-with-icon" data-ed="duplicate">${icon('copy')} Duplicate</button>` : ''}
        <span class="spacer"></span>
        <button type="button" class="secondary btn-with-icon" data-ed="close">${icon('x')} ${ro ? 'Close' : 'Cancel'}</button>
        ${ro ? '' : `<button type="submit" class="btn-with-icon">${icon('check')} ${t ? 'Save' : 'Create'}</button>`}
      </div>
    </form></div>`;
  m.hidden = false;
  const box = m.querySelector('.mbox');
  const $ = (sel) => box.querySelector(sel);
  const msg = (text) => { const p = $('#ed-msg'); p.textContent = text; p.className = 'message error'; p.hidden = !text; };

  // Leader: default (department leader, then parent leader) or explicit leader
  let leaderValue = v.leader_id ?? '';
  const fillLeader = () => {
    const dept = $('#ed-dept').value;
    const dl = dept ? deptLeader(dept) : null;
    const pl = parent ? parent.leader : null;
    const def = dl ?? pl;
    const src = dl ? `${dept} leader` : pl ? 'parent task leader' : '';
    $('#ed-leader').innerHTML = `<option value="">${esc(def ? `Default: ${nameOfPerson(def)} (${src})` : 'Default: none')}</option>` +
      eligibleLeaders().map(([pid, p]) => `<option value="${pid}"${pid === leaderValue ? ' selected' : ''}>${esc(p.name)}</option>`).join('');
    if (!t && !parent) $('#ed-codeinfo').textContent = `${dept || 'Department'}-nn – assigned on creation`;
  };

  const label = (n) => `${n.code} – ${n.name.length > 50 ? `${n.name.slice(0, 50)}…` : n.name}`;
  const fillDeps = () => {
    const chip = (sid, kind) => {
      const n = ALL.find((y) => y.id === sid);
      return `<span class="chip"><a href="#" data-goto="${sid}" title="${esc(n?.name ?? '')}">${esc(n?.code ?? '?')}</a>${ro ? '' : `<button type="button" data-rm="${kind}" data-tid="${sid}" aria-label="Remove ${esc(n?.code ?? '')}">×</button>`}</span>`;
    };
    $('#ed-deps').innerHTML = [...deps].map((d) => chip(d, 'dep')).join('') || '<span class="hint">none</span>';
    $('#ed-reqs').innerHTML = [...reqs].map((d) => chip(d, 'req')).join('') || '<span class="hint">none</span>';
    if (ro) return;
    const edges = graphWith(self, deps, reqs);
    const opts = (kind) => ALL.filter((n) => n.id !== self && !deps.has(n.id) && !reqs.has(n.id)).map((n) => {
      const loop = kind === 'dep' ? dependsOnPath(edges, n.id, self) : dependsOnPath(edges, self, n.id);
      return `<option value="${n.id}"${loop ? ' disabled' : ''}>${esc(label(n))}${loop ? ' (would create a loop)' : ''}</option>`;
    }).join('');
    $('#ed-add-dep').innerHTML = `<option value="">+ add a task this one depends on…</option>${opts('dep')}`;
    $('#ed-add-req').innerHTML = `<option value="">+ add a task that depends on this one…</option>${opts('req')}`;
  };

  const syncProgress = () => {
    if (ro || calc) return;
    const st = $('#ed-started'), co = $('#ed-completed');
    if (co.checked && !st.checked) st.checked = true;          // completed implies started
    $('#ed-started-on').disabled = !st.checked;
    $('#ed-completed-on').disabled = !co.checked;
    if (st.checked && !$('#ed-started-on').value) $('#ed-started-on').value = TODAY;
    if (co.checked && !$('#ed-completed-on').value) $('#ed-completed-on').value = TODAY;
    if (!st.checked) $('#ed-started-on').value = '';
    if (!co.checked) $('#ed-completed-on').value = '';
    const bl = $('#ed-blocked');
    $('#ed-blocked-reason').disabled = !bl.checked;
  };

  const warn = () => {
    const start = $('#ed-start').value, end = $('#ed-end').value, deadline = $('#ed-deadline').value;
    const completed = calc ? t.completed_on : $('#ed-completed-on').value;
    const out = [];
    if (start && end) {
      $('#ed-dur').textContent = end >= start ? `Duration ${days(dn(end) - dn(start) + 1)}` : '';
      if (end < start) out.push(['error', 'The planned end precedes the planned start.']);
      if (deadline) {
        const mg = dn(deadline) - dn(end);
        $('#ed-margin').textContent = `Margin ${days(mg)}`;
        if (!completed && mg < 0) out.push(['warn', 'The planned end is after the deadline: the task is at risk.']);
        else if (!completed && deadline < TODAY) out.push(['warn', 'The deadline has passed and the task is not completed.']);
      } else $('#ed-margin').textContent = '';
      const tight = [...deps].map((d) => ALL.find((n) => n.id === d)).filter((n) => n && n.end_date >= start);
      if (tight.length) {
        out.push(['warn', `Starts before the end of ${tight.map((n) => `${n.code} (${formatDate(n.end_date)})`).join(', ')}.` +
          (ro || calc ? '' : ' <button type="button" class="link" data-ed="align">Move after them, same duration</button>')]);
      }
      const late = [...reqs].map((r) => ALL.find((n) => n.id === r)).filter((n) => n && n.start_date <= end);
      if (late.length) out.push(['warn', `Ends after the start of ${late.map((n) => `${n.code} (${formatDate(n.start_date)})`).join(', ')}, which depend${late.length === 1 ? 's' : ''} on it.`]);
      if (parent && parent.deadline && end > parent.deadline) out.push(['warn', `Ends after the deadline of the parent task ${parent.code} (${formatDate(parent.deadline)}).`]);
      if (!calc && !completed && !$('#ed-started').checked && start < TODAY) out.push(['warn', 'The planned start has passed and the task is not started.']);
    }
    if (!completed && !$('#ed-leader').value && $('#ed-leader').selectedOptions[0]?.textContent === 'Default: none') {
      out.push(['warn', 'No leader: set the department leader in Members, or select a leader.']);
    }
    $('#ed-warn').innerHTML = out.length ? `<ul class="ed-warn">${out.map(([k, txt]) => `<li class="${k}">${txt}</li>`).join('')}</ul>` : '';
  };

  fillLeader();
  fillDeps();
  warn();

  // History, loaded when opened
  $('#ed-hist')?.addEventListener('toggle', async (e) => {
    if (!e.target.open || e.target.dataset.loaded) return;
    e.target.dataset.loaded = '1';
    const { data, error } = await supabase.from('task_history').select('*')
      .or(`task_id.eq.${t.id},changes->>depends_on.eq."${t.code}"`)
      .order('changed_at', { ascending: false }).limit(100);
    const body = $('#ed-hist-body');
    if (error) { body.innerHTML = `<p class="message error">${esc(errorText(error))}</p>`; return; }
    if (!data.length) { body.innerHTML = '<p class="hint">No change recorded yet.</p>'; return; }
    const names = { end_date: 'planned end', start_date: 'planned start', parent_id: 'parent', leader_id: 'leader', milestone_label: 'milestone',
      started_on: 'started', completed_on: 'completed', blocked_reason: 'blocked reason', teams: 'involved' };
    const show = (k, val) => {
      if (val == null || (Array.isArray(val) && !val.length)) return '—';
      if (k === 'leader_id') return nameOfPerson(val) || '—';
      if (Array.isArray(val)) return val.join(', ');
      if (/date|_on$|deadline/.test(k)) return formatDate(val);
      return String(val);
    };
    body.innerHTML = `<ul class="hist">${data.map((h) => {
      const when = new Date(h.changed_at).toLocaleString('en-GB', { timeZone: TIME_ZONE, dateStyle: 'short', timeStyle: 'short' });
      let what = esc(h.action);
      if (h.action === 'updated') {
        what = Object.entries(h.changes).map(([k, [a, b]]) => `${esc(names[k] ?? k)}: ${esc(show(k, a))} → ${esc(show(k, b))}`).join('; ');
      } else if (h.action.startsWith('dependency')) {
        what = h.task_id === t.id ? `${esc(h.action)}: depends on ${esc(h.changes.depends_on)}`
          : `${esc(h.task_code)}: ${esc(h.action)} on this task`;
      }
      return `<li><span class="mono">${esc(when)}</span> · ${esc(nameOfPerson(h.changed_by) || 'system')} · ${what}</li>`;
    }).join('')}</ul>`;
  });

  box.addEventListener('input', () => { m.dirty = true; warn(); });
  box.addEventListener('change', (e) => {
    m.dirty = true;
    if (e.target.id === 'ed-leader') leaderValue = e.target.value;
    if (e.target.id === 'ed-dept') fillLeader();
    if (e.target.id === 'ed-add-dep' && e.target.value) { deps.add(Number(e.target.value)); fillDeps(); }
    if (e.target.id === 'ed-add-req' && e.target.value) { reqs.add(Number(e.target.value)); fillDeps(); }
    if (['ed-started', 'ed-completed', 'ed-blocked'].includes(e.target.id)) {
      if (e.target.id === 'ed-started' && !e.target.checked) $('#ed-completed').checked = false;
      syncProgress();
    }
    warn();
  });

  box.addEventListener('click', async (e) => {
    const rm = e.target.closest('[data-rm]');
    if (rm) { (rm.dataset.rm === 'dep' ? deps : reqs).delete(Number(rm.dataset.tid)); m.dirty = true; fillDeps(); warn(); return; }
    const go = e.target.closest('[data-goto]');
    if (go) {
      e.preventDefault();
      if (m.dirty && !window.confirm('Discard the unsaved changes?')) return;
      openEditor(Number(go.dataset.goto));
      return;
    }
    const b = e.target.closest('[data-ed]');
    if (!b) return;
    const act = b.dataset.ed;
    if (act === 'close') requestClose();
    else if (act === 'align') {
      const latest = Math.max(...[...deps].map((d) => dn(ALL.find((n) => n.id === d).end_date)));
      const span = Math.max(dn($('#ed-end').value) - dn($('#ed-start').value), 0);
      $('#ed-start').value = iso(latest + 1);
      $('#ed-end').value = iso(latest + 1 + span);
      m.dirty = true; warn();
    } else if (act === 'add-sub') {
      if (m.dirty && !window.confirm('Discard the unsaved changes?')) return;
      openEditor(null, subtaskPreset(t));
    } else if (act === 'duplicate') {
      if (m.dirty && !window.confirm('Discard the unsaved changes?')) return;
      openEditor(null, {
        department: t.department, name: t.name, parent_id: t.parent_id, start_date: t.start_date, end_date: t.end_date,
        deadline: t.deadline, leader_id: t.leader_id, people: t.people ?? '', note: t.note ?? '', teams: [...t.teams],
        dependsOnIds: [...t.dependsOnIds],
      });
    } else if (act === 'delete') {
      const parts = [];
      if (children.length) parts.push(`${children.length} subtask(s) (${children.map((c) => c.code).join(', ')}) will be deleted as well`);
      const nDeps = t.dependsOnIds.length + t.requiredByIds.length;
      if (nDeps) parts.push(`${nDeps} dependency link(s) will be removed`);
      if (!window.confirm(`Delete ${t.code} – ${t.name}?${parts.length ? `\n\n${parts.join(';\n')}.` : ''}\n\nThe code will not be reused. A task with lab shifts cannot be deleted.`)) return;
      b.disabled = true;
      const { error } = await supabase.from('tasks').delete().eq('id', t.id);
      if (error) { b.disabled = false; msg(errorText(error)); return; }
      closeModal();
      await reload(`${t.code} deleted.`);
    }
  });

  $('#ed-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    if (ro) return;
    const fields = {
      department: $('#ed-dept').value,
      name: $('#ed-name').value.trim(),
      parent_id: v.parent_id,
      start_date: $('#ed-start').value,
      end_date: $('#ed-end').value,
      deadline: $('#ed-deadline').value || null,
      started_on: calc ? null : $('#ed-started-on').value || null,
      completed_on: calc ? null : $('#ed-completed-on').value || null,
      blocked: calc ? false : $('#ed-blocked').checked,
      blocked_reason: calc ? null : $('#ed-blocked-reason').value.trim() || null,
      leader_id: $('#ed-leader').value || null,
      people: $('#ed-people').value.trim() || null,
      note: $('#ed-note').value.trim() || null,
      teams: DEPTS.filter((k) => box.querySelector(`input[name="ed-team"][value="${k}"]`).checked),
      milestone_label: $('#ed-milestone').value.trim() || null,
    };
    const focus = (sel, text) => { msg(text); $(sel)?.focus(); };
    if (!fields.department) return focus('#ed-dept', 'Select the department.');
    if (!fields.name) return focus('#ed-name', 'The activity is required.');
    if (!fields.start_date || !fields.end_date) return focus('#ed-start', 'Planned start and planned end are required.');
    if (fields.end_date < fields.start_date) return focus('#ed-end', 'The planned end cannot precede the planned start.');
    if (fields.started_on > TODAY || fields.completed_on > TODAY) return msg('Start and completion dates cannot be in the future.');
    if (fields.completed_on && fields.completed_on < fields.started_on) return focus('#ed-completed-on', 'The completion date cannot precede the start date.');
    if (fields.blocked && !fields.blocked_reason) return focus('#ed-blocked-reason', 'Give the reason why the task is blocked.');
    const submit = box.querySelector('button[type="submit"]');
    submit.disabled = true;
    const { data: savedId, error } = await supabase.rpc('admin_save_task', {
      p_id: id,
      p_fields: fields,
      p_depends_on: [...deps],
      p_required_by: [...reqs],
      p_expected: t ? t.updated_at : null,
    });
    if (error) {
      submit.disabled = false;
      msg(errorText(error));
      if (error.message === 'Task modified by someone else') {
        $('#ed-msg').insertAdjacentHTML('beforeend', ' <button type="button" class="link" id="ed-reload">Reload the task</button>');
        $('#ed-reload').addEventListener('click', async () => { closeModal(); await reload(); openEditor(id); });
      }
      return;
    }
    closeModal();
    if (fields.parent_id) { ui.collapsed.delete(fields.parent_id); store('gantt-collapsed', [...ui.collapsed]); }
    await reload();
    const saved = ROWS.find((r) => r.id === savedId);
    toast(`${saved?.code ?? 'Task'} ${t ? 'saved' : 'created'}.`);
    highlight(savedId);
  });

  (ro ? box.querySelector('[data-ed="close"]') : t ? $('#ed-name') : $('#ed-dept')).focus();
}

function subtaskPreset(p) {
  return {
    parent_id: p.id, department: p.department, start_date: p.start_date,
    end_date: p.hasChildren ? p.end_date : iso(Math.min(dn(p.end_date), dn(p.start_date) + 6)),
  };
}

function highlight(id) {
  document.querySelectorAll(`[data-open="${id}"]`).forEach((el) => {
    el.classList.add('flash');
    setTimeout(() => el.classList.remove('flash'), 1600);
    if (el.classList.contains('tlink')) el.scrollIntoView({ block: 'nearest' });
  });
}

/* ---------- drag of the Gantt bars (admin, Edit timeline on, mouse only) ---------- */
let drag = null;
let suppressClick = false;

function dragTip(text, cx, cy) {
  let tip = document.getElementById('drag-tip');
  if (!tip) { tip = document.createElement('div'); tip.id = 'drag-tip'; document.body.appendChild(tip); }
  tip.textContent = text;
  tip.style.left = `${cx + 12}px`;
  tip.style.top = `${cy + 12}px`;
  tip.hidden = !text;
}

document.addEventListener('pointerdown', (e) => {
  const bar = e.target.closest?.('.bar.drag[data-bar]');
  if (!bar || !ADMIN || !ui.edit || e.button !== 0 || e.pointerType === 'touch') return;
  const t = ALL.find((n) => n.id === Number(bar.dataset.bar));
  if (!t) return;
  const mode = t.hasChildren ? 'move' : e.target.classList.contains('l') ? 'start' : e.target.classList.contains('r') ? 'end' : 'move';
  drag = { t, bar, mode, x0: e.clientX, moved: false, d: 0, start: t.start_date, end: t.end_date };
  bar.setPointerCapture?.(e.pointerId);
  e.preventDefault();
});

document.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const dx = e.clientX - drag.x0;
  if (!drag.moved && Math.abs(dx) < Math.max(6, ui.px / 2)) return;
  drag.moved = true;
  const n = Math.round(dx / ui.px);
  let s = dn(drag.t.start_date), en = dn(drag.t.end_date);
  if (drag.mode === 'move') { s += n; en += n; }
  else if (drag.mode === 'start') s = Math.min(s + n, en);
  else en = Math.max(en + n, s);
  drag.d = n;
  drag.start = iso(s);
  drag.end = iso(en);
  drag.bar.style.left = `${(s - ui.ganttStart) * ui.px}px`;
  drag.bar.style.width = `${Math.max((en - s + 1) * ui.px, 6)}px`;
  dragTip(`${drag.t.code}: ${formatDate(drag.start)} – ${formatDate(drag.end)}${drag.t.hasChildren ? ' (with subtasks)' : ''}`, e.clientX, e.clientY);
});

async function moveOrResize(t, mode, d, start, end, expected) {
  return mode === 'move'
    ? supabase.rpc('admin_move_task', { p_id: t.id, p_days: d, p_expected: expected })
    : supabase.rpc('admin_set_dates', { p_id: t.id, p_start: start, p_end: end, p_expected: expected });
}

async function endDrag(cancel) {
  const g = drag;
  drag = null;
  dragTip('', 0, 0);
  if (!g || !g.moved) return;
  suppressClick = true;
  setTimeout(() => { suppressClick = false; }, 0);
  if (cancel || (g.start === g.t.start_date && g.end === g.t.end_date)) { render(); return; }
  const t = g.t;
  const { error } = await moveOrResize(t, g.mode, g.d, g.start, g.end, t.updated_at);
  if (error) { toast(errorText(error)); await reload(); return; }
  await reload();
  const now = ALL.find((n) => n.id === t.id);
  const conflict = now?.depConflict.length ? ` Starts before the end of ${now.depConflict.join(', ')}.` : '';
  toast(`${t.code}: ${formatDate(g.start)} – ${formatDate(g.end)}.${conflict}`, {
    label: 'Undo',
    run: async () => {
      const cur = ROWS.find((r) => r.id === t.id);
      const { error: e2 } = await moveOrResize(t, g.mode, -g.d, t.start_date, t.end_date, cur?.updated_at);
      if (e2) { toast(errorText(e2)); await reload(); return; }
      await reload(`${t.code}: change undone.`);
    },
  });
}

document.addEventListener('pointerup', () => endDrag(false));
document.addEventListener('pointercancel', () => endDrag(true));
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (drag) { drag.moved = true; endDrag(true); return; }
    if (!modal().hidden) requestClose();
  } else if ((e.key === 'Enter' || e.key === ' ') && e.target.matches?.('tr[data-open]')) {
    e.preventDefault();
    openEditor(Number(e.target.dataset.open));
  }
});

/* ---------- render ---------- */
function render() {
  const v = document.getElementById('view');
  document.getElementById('g-nav').innerHTML = VIEWS.map(([k, l]) =>
    `<a href="#${k}"${k === ui.view ? ' aria-current="page"' : ''}>${l}</a>`).join('');
  ALL = build();
  stats(ALL);
  const keep = document.getElementById('gw');
  const scroll = keep ? [keep.scrollLeft, keep.scrollTop] : null;
  v.innerHTML = ui.view === 'gantt' ? gantt(ALL) : ui.view === 'table' ? table(ALL)
    : ui.view === 'depts' ? departments(ALL) : ui.view === 'events' ? events() : week(ALL);
  const gw = document.getElementById('gw');
  if (gw) {
    if (scroll) { [gw.scrollLeft, gw.scrollTop] = scroll; }
    else if (!render.done && ui.ganttStart != null) { gw.scrollLeft = Math.max(0, (TN - ui.ganttStart) * ui.px - 40); }
  }
  document.getElementById('g-sub').textContent = `RedPill (J2050) · ${ALL.length} tasks`;
  render.done = true;
}

/* ---------- events ---------- */
document.addEventListener('change', async (e) => {
  const el = e.target;
  if (el.closest?.('#g-modal')) return;
  if (el.dataset.ev) {
    const f = el.dataset.f;
    let val = el.value.trim();
    if (f === 'event_date' && !val) { render(); return; }
    if (f === 'note') val = val || null;
    await eventWrite(supabase.from('timeline_events').update({ [f]: val }).eq('id', Number(el.dataset.ev)));
    return;
  }
  if (el.id === 'gdept') { ui.dept = el.value; render(); }
  else if (el.id === 'hd') { ui.hideDone = el.checked; render(); }
  else if (el.id === 'edit-mode') { ui.edit = el.checked; render(); }
});

document.addEventListener('input', (e) => {
  if (e.target.id !== 'q') return;
  ui.q = e.target.value;
  const p = e.target.selectionStart;
  render();
  const q = document.getElementById('q');
  if (q) { q.focus(); q.setSelectionRange(p, p); }
});

document.addEventListener('click', async (e) => {
  if (e.target.closest?.('#g-modal')) {
    if (e.target.id === 'g-modal') requestClose();
    return;
  }
  if (suppressClick) { suppressClick = false; return; }
  const tog = e.target.closest?.('[data-toggle]');
  if (tog) {
    const pid = Number(tog.dataset.toggle);
    if (ui.collapsed.has(pid)) ui.collapsed.delete(pid); else ui.collapsed.add(pid);
    store('gantt-collapsed', [...ui.collapsed]);
    render();
    return;
  }
  const sub = e.target.closest?.('[data-addsub]');
  if (sub) { openEditor(null, subtaskPreset(ALL.find((n) => n.id === Number(sub.dataset.addsub)))); return; }
  const op = e.target.closest?.('[data-open]');
  if (op && !e.target.closest('input, select, button:not([data-open])')) { e.preventDefault(); openEditor(Number(op.dataset.open)); return; }
  const b = e.target.closest?.('[data-act]');
  if (!b) return;
  const act = b.dataset.act, id = Number(b.dataset.id);
  if (act === 'new-task') openEditor(null, ui.dept !== 'All' ? { department: ui.dept } : {});
  else if (act === 'zoom-in' || act === 'zoom-out') {
    const i = ZOOMS.indexOf(ui.px) + (act === 'zoom-in' ? 1 : -1);
    const gw = document.getElementById('gw');
    const centre = gw ? (gw.scrollLeft + gw.clientWidth / 2) / ui.px : null;
    ui.px = ZOOMS[Math.max(0, Math.min(ZOOMS.length - 1, i))];
    store('gantt-px', ui.px);
    render();
    const g2 = document.getElementById('gw');
    if (g2 && centre != null) g2.scrollLeft = Math.max(0, centre * ui.px - g2.clientWidth / 2);
  } else if (act === 'expand-all') { ui.collapsed.clear(); store('gantt-collapsed', []); render(); }
  else if (act === 'collapse-all') {
    ALL.filter((n) => n.hasChildren).forEach((n) => ui.collapsed.add(n.id));
    store('gantt-collapsed', [...ui.collapsed]);
    render();
  } else if (act === 'dept') { ui.deptView = b.dataset.t; render(); }
  else if (act === 'csv') exportCsv();
  else if (act === 'reload') await reload('Data reloaded.');
  else if (act === 'evdel') { ui.confirmDel = `ev${id}`; render(); }
  else if (act === 'evdel2') await eventWrite(supabase.from('timeline_events').delete().eq('id', id), 'Event deleted.');
  else if (act === 'evadd') {
    const date = document.getElementById('ev-date').value;
    const label = document.getElementById('ev-label').value.trim();
    const note = document.getElementById('ev-note').value.trim() || null;
    if (!date || !label) { toast('Date and label are required.'); return; }
    await eventWrite(supabase.from('timeline_events').insert({ event_date: date, label, note }), 'Event added.');
  }
});

function route() {
  const h = (location.hash || '').slice(1);
  ui.view = VIEWS.some(([k]) => k === h) ? h : 'gantt';
  ui.confirmDel = null;
  render();
}
window.addEventListener('hashchange', route);

/* ---------- start ---------- */
if (profile) {
  try {
    await load();
    route();
  } catch (err) {
    document.getElementById('view').innerHTML = '';
    toast(errorText(err));
  }
}
